object CatalogsFeedValidationWarningsData {

  def validated(d8a : CatalogsFeedValidationWarningsData, failFast : Boolean) : scala.util.Try[CatalogsFeedValidationWarnings] = d8a.validated(failFast)

  def fromJson(jason : ujson.Value) : CatalogsFeedValidationWarningsData = try {
        val data = read[CatalogsFeedValidationWarningsData](jason)
        data
    } catch {
      case NonFatal(e) => sys.error(s"Error creating CatalogsFeedValidationWarningsData from json '$jason': $e")
  }

  def fromJsonString(jason : String) : CatalogsFeedValidationWarningsData = {
        val parsed = try {
           read[ujson.Value](jason)
        } catch {
          case NonFatal(e) => sys.error(s"Error parsing json '$jason': $e")
        }
        fromJson(parsed)
  }

  def manyFromJsonString(jason : String) : Seq[CatalogsFeedValidationWarningsData] = try {
        read[List[CatalogsFeedValidationWarningsData]](jason)
    } catch {
        case NonFatal(e) => sys.error(s"Error parsing json '$jason' as list: $e")
    }

  def manyFromJsonStringValidated(jason : String, failFast : Boolean = false) : Try[Seq[CatalogsFeedValidationWarnings]] = {
      Try(manyFromJsonString(jason)).flatMap { list =>
        list.zipWithIndex.foldLeft(Try(Vector[CatalogsFeedValidationWarnings]())) {
          case (Success(list), (next, i)) => 
            next.validated(failFast) match {
              case Success(ok) => Success(list :+ ok)
              case Failure(err) => Failure(new Exception(s"Validation error on element $i: ${err.getMessage}", err))
            }
          case (fail, _)  => fail
        }
      }
    }

  def mapFromJsonString(jason : String) : Map[String, CatalogsFeedValidationWarningsData] = try {
        read[Map[String, CatalogsFeedValidationWarningsData]](jason)
    } catch {
        case NonFatal(e) => sys.error(s"Error parsing json '$jason' as map: $e")
    }


  def mapFromJsonStringValidated(jason : String, failFast : Boolean = false) : Try[Map[String, CatalogsFeedValidationWarnings]] = {
     Try(mapFromJsonString(jason)).flatMap { map =>
       map.foldLeft(Try(Map[String, CatalogsFeedValidationWarnings]())) {
         case (Success(map), (key, next)) =>
           next.validated(failFast) match {
             case Success(ok) => Success(map.updated(key, ok))
             case Failure(err) => Failure(new Exception(s"Validation error on element $key: ${err.getMessage}", err))
           }
         case (fail, _) => fail
